import type {ProjectReviewData,ProjectCase} from '../../src/domain/project-reactions';import {syntheticVersion} from './research-case';
export function groupFixture():ProjectReviewData{const seed=syntheticVersion();seed.payload.evidence.source_access='fulltext';seed.payload.evidence.evidence_type='directly_observed';seed.payload.evidence.measured_scope='net_conversion';seed.payload.evidence.epistemic_origin='experiment_report';seed.payload.experiment.origin_resolution_status='confirmed';seed.payload.experiment.original_experiment_id='SYNTHETIC original 1';seed.payload.experiment.independence_group_id='SYNTHETIC independent 1';Object.assign(seed.payload.experiment.conditions[0],{value_state:'reported',lower:80,upper:80});const second=structuredClone(seed);second.id='second-version';second.case_id='second-case';second.payload.experiment.original_experiment_id='SYNTHETIC original 2';second.payload.experiment.independence_group_id='SYNTHETIC independent 2';second.payload.evidence.evidence_type='proposed';second.payload.evidence.measured_scope=null;Object.assign(second.payload.experiment.conditions[0],{lower:120,upper:120});const versions=[seed,second].map((v,i)=>({...v,paper_id:'paper-'+i,current:true,payload:{...v.payload,evidence:{...v.payload.evidence,source_anchor_id:'anchor-'+i}}})) as ProjectCase[];return {identities:[{id:'identity',label:'SYNTHETIC reaction',seed_version_id:seed.id,definition:seed.payload,reason:'SYNTHETIC reviewed mapping'}],versions,mappings:versions.map(v=>({id:'mapping-'+v.id,identity_id:'identity',case_version_id:v.id,revision:1,decision:'include',mapping:v.payload.compounds.map(c=>({source:c.id,target:c.id})),reason:'SYNTHETIC manual equivalence'})),anchors:versions.map((v,i)=>({id:v.payload.evidence.source_anchor_id!,supersedes_anchor_id:null,passage_hash:'hash-'+i})),attestations:versions.map((v,i)=>({id:'attestation-'+i,anchor_id:v.payload.evidence.source_anchor_id!,receipt_id:'receipt-'+i,receipt_sha256:'pdfhash-'+i,passage_hash:'hash-'+i,revision:1,decision:'attested',reason:'SYNTHETIC human checked against receipt',created_by:'SYNTHETIC reviewer'})),reviews:versions.map((v,i)=>({id:'review-'+i,case_version_id:v.id,revision:1,decision:'accepted',source_attestation_id:'attestation-'+i,reason:'SYNTHETIC science review',created_by:'SYNTHETIC reviewer'}))};}
